# Base PaymentMethod class
class PaymentMethod:
    def __init__(self, amount):
        self.amount = amount

    def process_payment(self):
        print(f"Processing generic payment of ${self.amount}")

# Derived CreditCard class
class CreditCard(PaymentMethod):
    def __init__(self, amount, card_number, expiry_date):
        super().__init__(amount)
        self.card_number = card_number
        self.expiry_date = expiry_date

    def process_payment(self):
        print(f"Processing credit card payment of ${self.amount}")
        print(f"Using card ending in {self.card_number[-4:]}")

# Derived PayPal class
class PayPal(PaymentMethod):
    def __init__(self, amount, email):
        super().__init__(amount)
        self.email = email

    def process_payment(self):
        print(f"Processing PayPal payment of ${self.amount}")
        print(f"Using account {self.email}")

# Create a list of different payment method objects
payment_methods = [
    PaymentMethod(50),
    CreditCard(100, "4111111111111111", "12/25"),
    PayPal(75, "customer@example.com"),
    CreditCard(200, "5555555555554444", "01/26"),
    PayPal(25, "another@example.com")
]

# Function that demonstrates polymorphism
def process_all_payments(payment_list):
    print("Processing all payments:\n")
    for i, payment in enumerate(payment_list):
        print(f"Payment #{i+1}:")
        payment.process_payment()  # Polymorphic call - method behavior depends on object type
        print()  # Blank line for separation

# Call the function
process_all_payments(payment_methods)
